using System;using System.Drawing;using System.Linq;using System.Windows.Forms;using System.Globalization;using System.Collections.Generic;
namespace Tvxd.Meps {
 public sealed class Panel:UserControl {
  internal readonly TextBox roomCode=new TextBox{Text="R001"},roomName=new TextBox{Text=""},floor=new TextBox{Text=""},usage=new TextBox{Text=""},code=new TextBox{Text="D001"},name=new TextBox{Text=""},power=new TextBox{Text=""};
  static readonly string[] kinds=Symbols.Kinds; internal readonly ComboBox kind=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};internal readonly NumericUpDown rows=new NumericUpDown{Minimum=1,Maximum=20,Value=2},cols=new NumericUpDown{Minimum=1,Maximum=20,Value=3};
  internal readonly DataGridView rooms=Grid(),devices=Grid();readonly ListBox issues=new ListBox{Dock=DockStyle.Fill};internal readonly Label status=new Label{Dock=DockStyle.Fill,AutoSize=false,Text="Chọn Nhận / đọc lại mặt bằng để bắt đầu."};readonly Label doc=new Label{Dock=DockStyle.Fill};
  internal readonly Label selection=new Label{Dock=DockStyle.Fill,AutoSize=false,ForeColor=Color.FromArgb(13,69,86),Padding=new Padding(6,4,0,0)};internal readonly TabControl forms=new TabControl{Dock=DockStyle.Fill},data=new TabControl{Dock=DockStyle.Fill};
  internal readonly Dictionary<string,Button> cards=new Dictionary<string,Button>(),actions=new Dictionary<string,Button>();
  public Action<string,Meta,string,int,int> Request;
  internal readonly LibraryView library=new LibraryView();
  static DataGridView Grid(){return new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,MultiSelect=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells,BackgroundColor=Color.White,RowHeadersVisible=false};}
  public Panel(){Dock=DockStyle.Fill;BackColor=Color.FromArgb(239,244,247);Font=new Font("Segoe UI",9);Padding=new Padding(10);var root=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=7,ColumnCount=1};foreach(int h in new[]{36,28,40,-70,-30,45,55})root.RowStyles.Add(h<0?new RowStyle(SizeType.Percent,-h):new RowStyle(SizeType.Absolute,h));Controls.Add(root);root.Controls.Add(new Label{Text="TVXD MEPS 0.3.1  /  ĐIỆN MẶT BẰNG",Dock=DockStyle.Fill,Font=new Font("Segoe UI",14,FontStyle.Bold),ForeColor=Color.FromArgb(13,69,86)},0,0);root.Controls.Add(doc,0,1);
   var top=new FlowLayoutPanel{Dock=DockStyle.Fill};top.Controls.Add(B("Nhận / đọc lại mặt bằng","refresh"));top.Controls.Add(B("Xuất XLSX","export"));top.Controls.Add(B("Hoàn tác bước cuối","undo"));root.Controls.Add(top,0,2);
   var rtab=new TabPage("1 · Phòng");var r=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};Field(r,"Mã",roomCode,65);Field(r,"Tên phòng",roomName,130);Field(r,"Tầng",floor,75);Field(r,"Công năng",usage,140);r.Controls.Add(B("Chọn đường bao","room"));r.Controls.Add(B("Vẽ ranh phòng","trace"));r.Controls.Add(B("Sửa phòng chọn","roomedit"));rtab.Controls.Add(r);forms.TabPages.Add(rtab);
   // Device tab: block library cards on top, attribute fields and placement buttons below.
   var dtab=new TabPage("2 · Thiết bị");var dt=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};dt.RowStyles.Add(new RowStyle(SizeType.Absolute,124));dt.RowStyles.Add(new RowStyle(SizeType.Percent,100));
   var lib=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=1,ColumnCount=Symbols.Catalog.Length+1,Margin=new Padding(0)};lib.RowStyles.Add(new RowStyle(SizeType.Percent,100));for(int i=0;i<Symbols.Catalog.Length;i++){lib.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,128));lib.Controls.Add(Card(Symbols.Catalog[i]),i,0);}lib.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));lib.Controls.Add(selection,Symbols.Catalog.Length,0);dt.Controls.Add(lib,0,0);
   var d=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};kind.Items.AddRange(new object[]{"Đèn","Ổ cắm","Công tắc","Điểm cấp nguồn"});kind.SelectedIndex=0;Field(d,"Loại",kind,90);Field(d,"Mã",code,70);Field(d,"Tên",name,110);Field(d,"W",power,65);Field(d,"Hàng",rows,45);Field(d,"Cột",cols,45);d.Controls.Add(B("Đặt một thiết bị","place"));d.Controls.Add(B("Xem trước lưới đèn","grid"));d.Controls.Add(B("Sửa thiết bị chọn","edit"));dt.Controls.Add(d,0,1);dtab.Controls.Add(dt);forms.TabPages.Add(dtab);
   // 0.3: real-source block library (separate from the load table above).
   var ltab=new TabPage("3 · Thư viện khối");ltab.Controls.Add(library);forms.TabPages.Add(ltab);library.Message=Message;root.Controls.Add(forms,0,3);
   foreach(var pair in new[]{new object[]{"Danh sách phòng",rooms},new object[]{"Thiết bị / tải khai báo",devices},new object[]{"Cần kiểm tra",issues}}){var p=new TabPage((string)pair[0]);p.Controls.Add((Control)pair[1]);data.TabPages.Add(p);}root.Controls.Add(data,0,4);var bottom=new FlowLayoutPanel{Dock=DockStyle.Fill};bottom.Controls.Add(B("Tìm phòng chọn","findroom"));bottom.Controls.Add(B("Tìm thiết bị chọn","finddevice"));root.Controls.Add(bottom,0,5);root.Controls.Add(status,0,6);
   rooms.SelectionChanged+=(s,e)=>{var x=Selected(rooms);if(x!=null){roomCode.Text=x.Code;roomName.Text=x.Name;floor.Text=x.Level;usage.Text=x.Kind;}};
   // Device rows load into the form only on an explicit click/arrow key, so a grid rebind or tab switch cannot reset the chosen block.
   devices.CellClick+=(s,e)=>{if(e.RowIndex>=0)LoadDevice(devices.Rows[e.RowIndex].DataBoundItem as Row);};devices.KeyUp+=(s,e)=>{if(new[]{Keys.Up,Keys.Down,Keys.PageUp,Keys.PageDown,Keys.Home,Keys.End}.Contains(e.KeyCode))LoadDevice(Selected(devices));};
   kind.SelectedIndexChanged+=(s,e)=>Highlight();Highlight();
  }
  // Fixed two-row cell: label on one line above its input, so a long label can never wrap and squeeze the input.
  internal static void Field(FlowLayoutPanel p,string label,Control control,int width){var box=new TableLayoutPanel{ColumnCount=1,RowCount=2,Width=width+8,Height=53,Margin=new Padding(3)};box.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));box.RowStyles.Add(new RowStyle(SizeType.Absolute,20));box.RowStyles.Add(new RowStyle(SizeType.Percent,100));box.Controls.Add(new Label{Text=label,AutoSize=false,AutoEllipsis=true,Dock=DockStyle.Fill,TextAlign=ContentAlignment.BottomLeft,Margin=new Padding(0)},0,0);control.Width=width;control.Anchor=AnchorStyles.Left|AnchorStyles.Top;control.Margin=new Padding(0,2,0,0);box.Controls.Add(control,0,1);p.Controls.Add(box);}
  static Row Selected(DataGridView g){return g.CurrentRow==null?null:g.CurrentRow.DataBoundItem as Row;}
  // Choosing a card changes only the device kind; user-entered code, name and W stay as typed.
  Button Card(CatalogItem item){var b=new Button{Name="card_"+item.Kind,Tag=item.Kind,Text=item.Label,Image=Symbols.Render(item.Kind,64),TextImageRelation=TextImageRelation.ImageAboveText,Size=new Size(120,100),Margin=new Padding(3),FlatStyle=FlatStyle.Flat,BackColor=Color.White,AccessibleName="Chọn khối "+item.Label};b.Click+=(s,e)=>{kind.SelectedIndex=Array.IndexOf(kinds,item.Kind);Message("Đã chọn "+item.Label+". Nhập mã/tên rồi bấm Đặt một thiết bị và chọn vị trí trên Model.");};cards[item.Kind]=b;return b;}
  internal string SelectedKind{get{return kinds[kind.SelectedIndex];}}
  void Highlight(){string k=SelectedKind;foreach(var pair in cards){bool on=pair.Key==k;pair.Value.BackColor=on?Color.FromArgb(214,236,242):Color.White;pair.Value.FlatAppearance.BorderColor=on?Color.FromArgb(13,69,86):Color.Silver;pair.Value.FlatAppearance.BorderSize=on?3:1;}var item=Symbols.Catalog.FirstOrDefault(x=>x.Kind==k);selection.Text=(item!=null?"Đang chọn: "+item.Label:"Đang chọn: "+kind.SelectedItem+" (ngoài thư viện mẫu)")+"\r\n1. Bấm hình khối.\r\n2. Nhập Mã, Tên; W nếu có (trống = chưa biết).\r\n3. Bấm Đặt một thiết bị, chọn vị trí trên Model.\r\nKý hiệu mẫu minh họa, chưa phải ký hiệu công ty đã duyệt.";}
  internal void LoadDevice(Row x){if(x==null)return;code.Text=x.Code;name.Text=x.Name;int i=Array.IndexOf(kinds,x.Kind);if(i>=0)kind.SelectedIndex=i;power.Text=x.Watts.HasValue?x.Watts.Value.ToString(CultureInfo.CurrentCulture):"";}
  Button B(string caption,string action){var b=new Button{Text=caption,AutoSize=true,Height=28,FlatStyle=FlatStyle.Flat,BackColor=Color.White};actions[action]=b;b.Click+=(s,e)=>{try{Meta m=null;string handle=null;var selected=Selected(action=="edit"||action=="finddevice"?devices:rooms);if(new[]{"edit","roomedit","findroom","finddevice","grid"}.Contains(action)){if(selected==null)throw new Exception("Chọn một dòng trong bảng tương ứng.");handle=selected.Handle;}
   if(new[]{"room","trace","roomedit"}.Contains(action))m=new Meta{kind="ROOM",code=roomCode.Text.Trim(),name=roomName.Text.Trim(),level=floor.Text.Trim(),function=usage.Text.Trim()};
   if(new[]{"place","grid","edit"}.Contains(action)){double n;double? watts=null;if(!string.IsNullOrWhiteSpace(power.Text)){if(!double.TryParse(power.Text,NumberStyles.Float,CultureInfo.CurrentCulture,out n))throw new Exception("Nhập công suất bằng số W.");watts=n;}m=new Meta{kind=kinds[kind.SelectedIndex],code=code.Text.Trim(),name=name.Text.Trim(),watts=watts};}if(m!=null)Core.Validate(m);if(Request!=null)Request(action,m,handle,(int)rows.Value,(int)cols.Value);
   }catch(Exception ex){Message(ex.Message);}};return b;}
  public void Message(string s){status.Text=s;}
  public void Display(string drawing,Snapshot s){doc.Text=drawing+"  •  "+s.rooms.Count+" phòng / "+s.devices.Count+" thiết bị";rooms.DataSource=s.rooms.ToArray();devices.DataSource=s.devices.ToArray();foreach(var grid in new[]{rooms,devices})foreach(string col in new[]{"Id","Handle"})if(grid.Columns.Contains(col))grid.Columns[col].Visible=false;foreach(var grid in new[]{rooms,devices})foreach(DataGridViewColumn c in grid.Columns){var titles=new[]{"Id:ID","Handle:Handle","Code:Mã","Name:Tên","Level:Tầng","Kind:Loại / công năng","Room:Phòng","AreaM2:Diện tích m²","Watts:Công suất W","Issue:Cần kiểm tra"};foreach(var title in titles){var bits=title.Split((char)58);if(c.Name==bits[0])c.HeaderText=bits[1];}}if(rooms.Columns.Contains("Room"))rooms.Columns["Room"].Visible=false;if(devices.Columns.Contains("AreaM2"))devices.Columns["AreaM2"].Visible=false;issues.Items.Clear();issues.Items.Add("BỐ TRÍ SƠ BỘ — chưa kiểm chứng thiết kế điện/chiếu sáng.");foreach(var issue in s.issues)issues.Items.Add(issue);Message(s.issues.Count+" mục cần kiểm tra. Sửa hình bằng MOVE/UNDO rồi bấm Đọc lại; chưa tự lưu DWG.");}
 }
}
